import { loadState, saveState, resetLocal } from './storage.js';
import { STATUS_META, TYPE_OPTIONS, PRIORITIES, defaultState } from './state.js';
import { uid, localISODate, parseLocalDate, dateKey, escapeHTML, formatDate, formatLongDate, formatTime, relativeDue, daysBetween, isPastDue, sortAssignments, downloadJSON } from './utils.js';
import { parseBulk } from './parser.js';
import { cloudConfigured, observeAuth, signIn, signOutCloud, pushCloud, pullCloud, watchCloud } from './cloud.js';
import { renderStudy } from './study-v2.js';

let state=loadState();
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
const view=$('#view'), modalRoot=$('#modalRoot'), toastRoot=$('#toastRoot');
const NAV=[['home','⌂','Home'],['calendar','▦','Calendar'],['assignments','✓','Assignments'],['study','◆','Study'],['add','＋','Add'],['completed','◷','Completed'],['classes','◉','Classes'],['settings','⚙','Settings']];

function persist(sync=true){ saveState(state); applyTheme(); if(sync) queueCloud(); }
let cloudTimer, stopCloudWatch=null, cloudSyncUid=null;
function queueCloud(){ if(!state.auth.user||!state.auth.cloudEnabled) return; clearTimeout(cloudTimer); cloudTimer=setTimeout(async()=>{try{state.auth.lastSync=await pushCloud(state.auth.user.uid,state);saveState(state);}catch(e){console.warn('Cloud save failed',e);toast('Cloud save failed — local copy is still safe');}},350); }

function assignmentStamp(a){ return Date.parse(a?.updatedAt||a?.completedAt||a?.createdAt||0)||0; }
function mergeAssignments(local=[],remote=[]){
  const merged=new Map(local.map(a=>[a.id,a]));
  for(const r of remote||[]){
    const l=merged.get(r.id);
    if(!l){merged.set(r.id,r);continue;}
    // Newest assignment change wins. Older saved copies can no longer undo completion.
    merged.set(r.id,assignmentStamp(r)>assignmentStamp(l)?r:l);
  }
  return [...merged.values()];
}
function studyStamp(x){return Date.parse(x?.updatedAt||x?.createdAt||0)||0;}
function mergeStudySets(local=[],remote=[]){
  const merged=new Map(local.map(x=>[x.id,x]));
  for(const r of remote||[]){
    const l=merged.get(r.id);
    if(!l||studyStamp(r)>studyStamp(l))merged.set(r.id,r);
  }
  return [...merged.values()];
}
function mergeRemoteState(remote,user){
  if(!remote) return state;
  const auth={user:{uid:user.uid,email:user.email,displayName:user.displayName},cloudEnabled:true,lastSync:remote.auth?.lastSync||state.auth.lastSync};
  return {
    ...defaultState(),
    ...state,
    ...remote,
    assignments:mergeAssignments(state.assignments,remote.assignments||[]),
    classes:Array.isArray(remote.classes)&&remote.classes.length?remote.classes:state.classes,
    widgets:Array.isArray(remote.widgets)?remote.widgets:state.widgets,
    studySets:mergeStudySets(state.studySets||[],remote.studySets||[]),
    settings:{...state.settings,...(remote.settings||{}),statusColors:{...state.settings.statusColors,...(remote.settings?.statusColors||{})},shortcuts:{...state.settings.shortcuts,...(remote.settings?.shortcuts||{})}},
    ui:state.ui,
    auth
  };
}
async function startCloudSync(user){
  if(!user) return;
  state.auth.user={uid:user.uid,email:user.email,displayName:user.displayName};
  state.auth.cloudEnabled=true;
  if(cloudSyncUid===user.uid&&stopCloudWatch){saveState(state);return;}
  cloudSyncUid=user.uid;
  if(stopCloudWatch){stopCloudWatch();stopCloudWatch=null;}
  try{
    const remote=await pullCloud(user.uid);
    if(remote) state=mergeRemoteState(remote,user);
    saveState(state);
    render();
    // Write the reconciled copy back so every device starts from the same truth.
    state.auth.lastSync=await pushCloud(user.uid,state);
    saveState(state);
    stopCloudWatch=await watchCloud(user.uid,remoteState=>{
      const before=JSON.stringify([state.assignments,state.studySets]);
      state=mergeRemoteState(remoteState,user);
      saveState(state);
      if(JSON.stringify([state.assignments,state.studySets])!==before) render();
    });
  }catch(e){
    console.error('Cloud sync startup failed',e);
    saveState(state);
  }
}

function applyTheme(){
  const root=document.documentElement; root.style.setProperty('--accent',state.settings.accent||'#7c5cff');
  for(const [k,v] of Object.entries(state.settings.statusColors||{})) root.style.setProperty(`--status-${k}`,v);
}

function getClass(id){return state.classes.find(c=>c.id===id)||state.classes[0];}
function isScheduleOnly(a){return !!getClass(a.classId)?.scheduleOnly;}
function scheduleDatePassed(a){return isScheduleOnly(a)&&a.dueDate&&a.dueDate<localISODate();}
function actualStatus(a){ return !isScheduleOnly(a)&&state.settings.autoOverdue&&isPastDue(a)?'overdue':a.status; }
function statusMeta(status){return {label:STATUS_META[status]?.label||status,color:state.settings.statusColors?.[status]||STATUS_META[status]?.color||'#888'};}
function activeAssignments(){return state.assignments.filter(a=>!['completed','skipped'].includes(a.status)&&!scheduleDatePassed(a));}
function dueAssignments(){return activeAssignments().filter(a=>!isScheduleOnly(a));}
function recentlyCompleted(){ const days=Number(state.settings.archiveDays)||21; return state.assignments.filter(a=>a.status==='completed'&&a.completedAt&&((Date.now()-new Date(a.completedAt))/86400000)<=days); }
function archivedCompleted(){ const days=Number(state.settings.archiveDays)||21; return state.assignments.filter(a=>a.status==='completed'&&a.completedAt&&((Date.now()-new Date(a.completedAt))/86400000)>days); }

function setRoute(route){ state.ui.route=route; if(route==='calendar') state.ui.calendarCursor=localISODate(new Date()).slice(0,7); persist(false); render(); window.scrollTo({top:0,behavior:'smooth'}); }
function renderNav(){
  $('#desktopNav').innerHTML=NAV.map(([r,i,l])=>`<button class="nav-item ${state.ui.route===r?'active':''}" data-route="${r}"><span class="nav-icon">${i}</span>${l}</button>`).join('');
  $('#mobileNav').innerHTML=[['home','⌂','Home'],['calendar','▦','Calendar'],['__add','＋',''],['assignments','✓','Tasks'],['study','◆','Study'],['settings','⚙','More']].map(([r,i,l])=>`<button class="${r==='__add'?'mobile-plus':''} ${state.ui.route===r?'active':''}" data-route="${r}"><span class="m-icon">${i}</span>${l}</button>`).join('');
  $$('[data-route]').forEach(b=>b.onclick=()=>b.dataset.route==='__add'?openAssignmentForm():setRoute(b.dataset.route));
}
function pageTitle(){return NAV.find(n=>n[0]===state.ui.route)?.[2]||'CourseFlow';}
function render(){
  renderNav(); $('#pageTitle').textContent=pageTitle(); $('#pageEyebrow').textContent=state.ui.route==='home'?'YOUR SCHOOL DASHBOARD':'COURSEFLOW';
  const map={home:renderHome,calendar:renderCalendar,assignments:renderAssignments,study:()=>renderStudy(view,state,{persist,toast}),add:renderAdd,completed:renderCompleted,classes:renderClasses,settings:renderSettings};
  view.innerHTML=''; (map[state.ui.route]||renderHome)(); bindCommon();
}
function bindCommon(){ $$('[data-open-assignment]').forEach(el=>el.onclick=e=>{e.stopPropagation();openAssignmentDetail(el.dataset.openAssignment)}); $$('[data-day]').forEach(el=>el.onclick=()=>openDay(el.dataset.day)); }

function greeting(){ const h=new Date().getHours(); return h<12?'Good morning':h<17?'Good afternoon':'Good evening'; }
function nextDue(){ return sortAssignments(dueAssignments().filter(a=>a.dueDate),'dueSoonest')[0]; }
function workloadForDate(iso){ const list=dueAssignments().filter(a=>a.dueDate===iso); const points=list.reduce((s,a)=>s+(a.points||0),0); const score=list.length+Math.min(points/40,4); return score>=6?['Heavy','🔴']:score>=3?['Moderate','🟡']:list.length?['Light','🟢']:['Clear','⚪']; }

function renderHome(){
  const today=new Date(), todayIso=localISODate(today), next=nextDue(), week=Array.from({length:5},(_,i)=>{const d=new Date(today);d.setDate(today.getDate()+i);return d;});
  const thisWeek=dueAssignments().filter(a=>a.dueDate&&daysBetween(today,parseLocalDate(a.dueDate))>=0&&daysBetween(today,parseLocalDate(a.dueDate))<=6);
  const done7=state.assignments.filter(a=>a.status==='completed'&&a.completedAt&&Date.now()-new Date(a.completedAt)<7*86400000);
  const pieces=[];
  if(state.settings.showGreeting) pieces.push(`<section class="card hero"><div class="eyebrow">${escapeHTML(formatLongDate(todayIso).toUpperCase())}</div><h2>${greeting()}</h2><p>${next?`Your next deadline is <strong>${escapeHTML(next.name)}</strong> ${escapeHTML(relativeDue(next.dueDate,next.dueTime).toLowerCase())}.`:'You are clear — no upcoming deadlines are saved.'}</p><div class="hero-meta"><span class="pill"><strong>${thisWeek.length}</strong> due this week</span><span class="pill"><strong>${done7.length}</strong> completed lately</span>${next&&next.points!=null?`<span class="pill"><strong>${next.points}</strong> pts next</span>`:''}</div></section>`);
  const stats=[];
  if(state.settings.showStats){stats.push(`<div class="card stat"><div class="stat-value">${thisWeek.length}</div><div class="stat-label">Due in next 7 days</div></div>`,`<div class="card stat"><div class="stat-value">${done7.length}</div><div class="stat-label">Completed in 7 days</div></div>`,`<div class="card stat"><div class="stat-value">${dueAssignments().filter(a=>actualStatus(a)==='overdue').length}</div><div class="stat-label">Overdue</div></div>`);}
  if(state.settings.showCountdown&&next){ const diffMs=Math.max(0,(parseLocalDate(next.dueDate)?.setHours(...((next.dueTime||'23:59').split(':').map(Number)),0,0)||Date.now())-Date.now()); const hrs=Math.floor(diffMs/3600000), days=Math.floor(hrs/24); stats.push(`<div class="card stat"><div class="stat-value">${days?days+'d':hrs+'h'}</div><div class="stat-label">Until next deadline</div></div>`); }
  if(stats.length) pieces.push(`<div class="grid grid-4 mt-16">${stats.join('')}</div>`);

  pieces.push(`<div class="grid grid-2 mt-16"><section class="card"><div class="card-title-row"><div class="card-title">Up next</div><button class="ghost-btn" data-route-go="assignments">View all</button></div><div class="assignment-list">${assignmentCards(sortAssignments(activeAssignments().filter(a=>a.dueDate),'dueSoonest').slice(0,6))||empty('No upcoming assignments')}</div></section>${state.settings.showWorkload?`<section class="card"><div class="card-title-row"><div class="card-title">Workload</div><span class="subtle">Next 5 days</span></div>${week.map(d=>{const iso=dateKey(d),[label,icon]=workloadForDate(iso);const count=dueAssignments().filter(a=>a.dueDate===iso).length;return `<div class="switch-row"><div><strong>${d.toLocaleDateString([], {weekday:'long'})}</strong><div class="subtle">${formatDate(iso,{month:'short',day:'numeric'})} • ${count} assignment${count===1?'':'s'}</div></div><span>${icon} ${label}</span></div>`}).join('')}</section>`:''}</div>`);

  if(state.settings.classPointTracking&&state.settings.showPoints){ pieces.push(`<section class="card mt-16"><div class="card-title-row"><div class="card-title">Points by class</div><span class="subtle">Separate totals</span></div><div class="grid grid-3">${state.classes.filter(c=>c.id!=='general'||state.assignments.some(a=>a.classId==='general')).map(c=>{const all=state.assignments.filter(a=>a.classId===c.id&&a.points!=null&&!c.scheduleOnly),done=all.filter(a=>a.status==='completed'),donePts=done.reduce((s,a)=>s+(a.points||0),0),remain=all.filter(a=>a.status!=='completed').reduce((s,a)=>s+(a.points||0),0),total=donePts+remain,pct=total?Math.round(donePts/total*100):0;return `<div class="card soft"><div class="flex between center"><strong>${state.settings.showClassIcons?escapeHTML(c.icon||'📚')+' ':''}${escapeHTML(c.name)}</strong><span class="subtle">${pct}%</span></div><div class="progress-track"><div class="progress-bar" style="width:${pct}%;background:${c.color}"></div></div><div class="subtle mt-8">${donePts} completed • ${remain} remaining</div></div>`}).join('')}</div></section>`); }

  if(state.settings.showMiniCalendar) pieces.push(`<section class="card mt-16"><div class="card-title-row"><div class="card-title">Mini calendar</div><button class="ghost-btn" data-route-go="calendar">Open calendar</button></div>${miniCalendar()}</section>`);
  if(state.settings.showWidgets) pieces.push(renderWidgets());
  view.innerHTML=pieces.join('');
  $$('[data-route-go]').forEach(b=>b.onclick=()=>setRoute(b.dataset.routeGo)); bindWidgetButtons();
}

function assignmentCards(items){ return items.map(a=>{const c=getClass(a.classId),schedule=!!c.scheduleOnly,s=schedule?{label:'Scheduled',color:c.color}:statusMeta(actualStatus(a));return `<div class="assignment-card" data-open-assignment="${a.id}" style="--class-color:${c.color}"><div class="assignment-color"></div><div class="assignment-main"><div class="assignment-name">${state.settings.showClassIcons?escapeHTML(c.icon||'')+' ':''}${escapeHTML(a.name)}</div><div class="assignment-meta"><span>${escapeHTML(c.name)}</span>${a.dueDate?`<span>${schedule?'Scheduled '+escapeHTML(formatDate(a.dueDate,{month:'short',day:'numeric'})):escapeHTML(relativeDue(a.dueDate,a.dueTime))}</span>`:''}${a.points!=null?`<span>${a.points} pts</span>`:''}<span>${escapeHTML(s.label)}</span></div></div><div class="assignment-right"><span class="status-dot" style="--status-color:${s.color}"></span><span class="priority-badge">${schedule?'schedule':escapeHTML(a.priority||'normal')}</span></div></div>`}).join(''); }
function empty(text){return `<div class="empty">${escapeHTML(text)}</div>`;}

function miniCalendar(){ const d=new Date(), y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1),start=new Date(y,m,1-first.getDay());let cells='';for(let i=0;i<35;i++){const x=new Date(start);x.setDate(start.getDate()+i);const iso=dateKey(x),count=activeAssignments().filter(a=>a.dueDate===iso).length;cells+=`<div style="padding:7px;text-align:center;border-radius:8px;background:${iso===localISODate(d)?'var(--accent)':'transparent'};color:${x.getMonth()!==m?'var(--muted)':'var(--text)'};font-size:11px">${x.getDate()}${count?`<div style="width:4px;height:4px;border-radius:50%;background:${iso===localISODate(d)?'white':'var(--accent)'};margin:3px auto 0"></div>`:''}</div>`;}return `<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:3px"><div class="subtle right">S</div><div class="subtle right">M</div><div class="subtle right">T</div><div class="subtle right">W</div><div class="subtle right">T</div><div class="subtle right">F</div><div class="subtle right">S</div>${cells}</div>`; }

function renderWidgets(){return `<section class="mt-16"><div class="card-title-row"><div><div class="card-title">Your board</div><div class="subtle">Notes, images, links, and custom cards</div></div><div class="flex gap-8"><button id="toggleWidgetEdit" class="ghost-btn">${state.settings.dashboardEditing?'Done':'Customize'}</button><button id="addWidget" class="primary-btn">+ Widget</button></div></div><div class="widget-board">${state.widgets.map(w=>`<article class="card widget ${escapeHTML(w.size||'')} ${state.settings.dashboardEditing?'editing':''}"><div class="widget-actions"><button class="danger-btn" data-delete-widget="${w.id}">Delete</button></div><div class="card-title">${escapeHTML(w.title)}</div><div class="subtle mt-12">${w.type==='image'&&w.content?`<img src="${escapeHTML(w.content)}" alt="${escapeHTML(w.title)}">`:escapeHTML(w.content).replace(/\n/g,'<br>')}</div></article>`).join('')||empty('No widgets yet')}</div></section>`;}
function bindWidgetButtons(){ const t=$('#toggleWidgetEdit');if(t)t.onclick=()=>{state.settings.dashboardEditing=!state.settings.dashboardEditing;persist();render();}; const a=$('#addWidget');if(a)a.onclick=openWidgetForm; $$('[data-delete-widget]').forEach(b=>b.onclick=()=>{state.widgets=state.widgets.filter(w=>w.id!==b.dataset.deleteWidget);persist();render();}); }

function renderCalendar(){ const [y,m]=state.ui.calendarCursor.split('-').map(Number),cursor=new Date(y,m-1,1); view.innerHTML=`<div class="calendar-toolbar"><div class="flex gap-8 center"><button id="calPrev" class="icon-btn">←</button><button id="calToday" class="ghost-btn">Today</button><button id="calNext" class="icon-btn">→</button><h2 class="mb-0" style="margin-left:6px">${cursor.toLocaleDateString([],{month:'long',year:'numeric'})}</h2></div><div class="segmented">${['month','week','agenda'].map(v=>`<button data-cal-view="${v}" class="${state.ui.calendarView===v?'active':''}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div><div id="calendarBody"></div>`;
  $('#calPrev').onclick=()=>shiftCalendar(-1);$('#calNext').onclick=()=>shiftCalendar(1);$('#calToday').onclick=()=>{state.ui.calendarCursor=localISODate().slice(0,7);persist(false);renderCalendar();};$$('[data-cal-view]').forEach(b=>b.onclick=()=>{state.ui.calendarView=b.dataset.calView;persist(false);renderCalendar();}); renderCalendarBody(); }
function shiftCalendar(delta){const [y,m]=state.ui.calendarCursor.split('-').map(Number),d=new Date(y,m-1,1);if(state.ui.calendarView==='month')d.setMonth(d.getMonth()+delta);else d.setDate(d.getDate()+delta*7);state.ui.calendarCursor=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;persist(false);renderCalendar();}
function renderCalendarBody(){ const body=$('#calendarBody');if(state.ui.calendarView==='month')body.innerHTML=monthView();else if(state.ui.calendarView==='week')body.innerHTML=weekView();else body.innerHTML=agendaView();bindCommon(); }
function monthView(){const [y,mn]=state.ui.calendarCursor.split('-').map(Number),m=mn-1,first=new Date(y,m,1),start=new Date(y,m,1-first.getDay()),headers=['SUN','MON','TUE','WED','THU','FRI','SAT'];let cells='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const iso=dateKey(d),items=sortAssignments(activeAssignments().filter(a=>a.dueDate===iso),'dueSoonest'),colors=[...new Set(items.map(a=>getClass(a.classId).color))].slice(0,4);cells+=`<div class="day-cell ${d.getMonth()!==m?'other-month':''} ${iso===localISODate()?'today':''}" data-day="${iso}"><div class="day-head"><span class="day-number">${d.getDate()}</span><span class="day-class-dots">${colors.map(c=>`<span class="day-class-dot" style="--dot:${c}"></span>`).join('')}</span></div>${items.slice(0,3).map(a=>`<div class="cal-item" data-open-assignment="${a.id}" style="--class-color:${getClass(a.classId).color}">${state.settings.showClassIcons?escapeHTML(getClass(a.classId).icon||'')+' ':''}${escapeHTML(a.name)}</div>`).join('')}${items.length>3?`<div class="more-link">+${items.length-3} more</div>`:''}</div>`;}return `<div class="calendar-scroll"><div class="calendar-grid">${headers.map(h=>`<div class="weekday">${h}</div>`).join('')}${cells}</div></div>`; }
function startOfWeek(){const [y,m]=state.ui.calendarCursor.split('-').map(Number),ref=new Date(y,m-1,1),today=new Date(); if(today.getFullYear()===y&&today.getMonth()===m-1) ref.setDate(today.getDate()); ref.setDate(ref.getDate()-ref.getDay());return ref;}
function weekView(){const s=startOfWeek();return `<div class="week-view">${Array.from({length:7},(_,i)=>{const d=new Date(s);d.setDate(s.getDate()+i);const iso=dateKey(d),items=sortAssignments(activeAssignments().filter(a=>a.dueDate===iso));return `<section class="card week-col ${iso===localISODate()?'today':''}" data-day="${iso}"><div class="week-col-head"><strong>${d.toLocaleDateString([],{weekday:'short'})}</strong><span class="subtle">${formatDate(iso,{month:'short',day:'numeric'})}</span></div><div class="assignment-list">${assignmentCards(items)||'<div class="subtle">Nothing due</div>'}</div></section>`}).join('')}</div>`;}
function agendaView(){const start=startOfWeek();return Array.from({length:14},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const iso=dateKey(d),items=sortAssignments(activeAssignments().filter(a=>a.dueDate===iso));return `<section class="agenda-day"><div class="agenda-date">${escapeHTML(formatLongDate(iso))}</div>${items.length?`<div class="assignment-list">${assignmentCards(items)}</div>`:'<div class="subtle">No assignments</div>'}</section>`}).join('');}

function renderAssignments(){ const f=state.ui.assignmentFilters, filtered=activeAssignments().filter(a=>f.search===' '||!f.search||[a.name,a.description,a.notes,(a.tags||[]).join(' '),getClass(a.classId).name,getClass(a.classId).teacher].join(' ').toLowerCase().includes(f.search.toLowerCase())).filter(a=>f.classId==='all'||a.classId===f.classId).filter(a=>f.status==='all'||actualStatus(a)===f.status).filter(a=>f.priority==='all'||a.priority===f.priority).filter(a=>f.type==='all'||a.type===f.type);const list=sortAssignments(filtered,f.sort);
  view.innerHTML=`<div class="filters"><div class="field search-field"><label>Search</label><input id="fSearch" class="input" placeholder="Assignments, notes, teachers..." value="${escapeHTML(f.search)}"></div>${filterSelect('fClass','Class',[['all','All classes'],...state.classes.map(c=>[c.id,c.name])],f.classId)}${filterSelect('fStatus','Status',[['all','All statuses'],...Object.entries(STATUS_META).map(([k,v])=>[k,v.label])],f.status)}${filterSelect('fPriority','Priority',[['all','All priorities'],...PRIORITIES.map(p=>[p,p])],f.priority)}${filterSelect('fType','Type',[['all','All types'],...TYPE_OPTIONS.map(t=>[t,t])],f.type)}${filterSelect('fSort','Sort',[['dueSoonest','Due soonest'],['dueLatest','Due latest'],['pointsHigh','Highest points'],['pointsLow','Lowest points'],['priority','Priority'],['class','Class'],['recent','Recently added']],f.sort)}</div><div class="flex between center wrap gap-12"><div class="subtle">${list.length} assignment${list.length===1?'':'s'}</div><button id="assignmentAdd" class="primary-btn">+ New assignment</button></div><div class="assignment-list mt-16">${assignmentCards(list)||empty('No assignments match your filters')}</div>`;
  $('#assignmentAdd').onclick=()=>openAssignmentForm(); [['fSearch','search'],['fClass','classId'],['fStatus','status'],['fPriority','priority'],['fType','type'],['fSort','sort']].forEach(([id,key])=>{const el=$('#'+id);el.oninput=()=>{state.ui.assignmentFilters[key]=el.value;persist(false);renderAssignments();};}); }
function filterSelect(id,label,opts,value){return `<div class="field filter-field"><label>${label}</label><select id="${id}">${opts.map(([v,l])=>`<option value="${escapeHTML(v)}" ${v===value?'selected':''}>${escapeHTML(l)}</option>`).join('')}</select></div>`;}

function renderAdd(){view.innerHTML=`<div class="grid grid-2"><section class="card hover" id="singleAddCard"><div style="font-size:30px">＋</div><h2>Single assignment</h2><p class="muted">Fast entry with optional details, points, tags, priority, and subtasks.</p><button class="primary-btn">Add assignment</button></section><section class="card hover" id="bulkAddCard"><div style="font-size:30px">≡</div><h2>Bulk import</h2><p class="muted">Paste many assignments, group by class, detect date meanings, then review before importing.</p><button class="primary-btn">Open bulk importer</button></section></div><section class="card mt-16"><div class="card-title">Supported bulk format</div><pre style="white-space:pre-wrap;color:var(--muted);line-height:1.6">@class AP Calculus\nHomework 3.1 | due: 2026-08-25 | 11:59 PM | 10 pts\nHomework 3.2 | due: 2026-08-27 | 15 pts\n\n@class English\nEssay Outline | due: August 28 | 20 pts</pre><div class="subtle">The importer also accepts looser text. It will preview anything uncertain before saving.</div></section>`;$('#singleAddCard').onclick=openAssignmentForm;$('#bulkAddCard').onclick=openBulkImporter;}

function renderCompleted(){const recent=sortAssignments(recentlyCompleted(),'recent'),archive=sortAssignments(archivedCompleted(),'recent');view.innerHTML=`<div class="grid grid-2"><section class="card"><div class="card-title-row"><div><div class="card-title">Recently completed</div><div class="subtle">Last ${state.settings.archiveDays} days</div></div><span class="pill"><strong>${recent.length}</strong></span></div><div class="assignment-list">${assignmentCards(recent)||empty('Nothing completed recently')}</div></section><section class="card"><div class="card-title-row"><div><div class="card-title">Archive</div><div class="subtle">Older completed work stays out of the way</div></div><span class="pill"><strong>${archive.length}</strong></span></div><div class="assignment-list">${assignmentCards(archive)||empty('Archive is empty')}</div></section></div>`;bindCommon();}

function renderClasses(){view.innerHTML=`<div class="flex between center wrap gap-12"><div class="subtle">${state.classes.length} class${state.classes.length===1?'':'es'}</div><button id="addClass" class="primary-btn">+ Add class</button></div><div class="class-grid mt-16">${state.classes.map(c=>{const upcoming=activeAssignments().filter(a=>a.classId===c.id).length,pts=state.assignments.filter(a=>a.classId===c.id&&a.points!=null).reduce((s,a)=>s+(a.points||0),0);return `<article class="card class-card hover" data-class="${c.id}" style="--class-color:${c.color}"><div class="class-topline"></div><div class="class-icon">${escapeHTML(c.icon||'📚')}</div><div class="class-name">${escapeHTML(c.name)}</div><div class="class-info"><span>${escapeHTML(c.teacher||'No teacher saved')}</span><span>${c.period?`Period ${escapeHTML(c.period)} • `:''}${escapeHTML(c.room||'No room')}</span><span>${upcoming} active • ${pts} listed points</span></div></article>`}).join('')}</div>`;$('#addClass').onclick=()=>openClassForm();$$('[data-class]').forEach(e=>e.onclick=()=>openClassForm(e.dataset.class));}

function renderSettings(){const sec=state.ui.settingsSection;const sections=[['appearance','Appearance'],['dashboard','Dashboard'],['calendar','Calendar'],['assignments','Assignments'],['shortcuts','Shortcuts'],['data','Data & Sync']];view.innerHTML=`<div class="settings-grid"><aside class="card settings-nav">${sections.map(([k,l])=>`<button data-settings="${k}" class="${sec===k?'active':''}">${l}</button>`).join('')}</aside><section id="settingsPanel" class="card"></section></div>`;$$('[data-settings]').forEach(b=>b.onclick=()=>{state.ui.settingsSection=b.dataset.settings;persist(false);renderSettings();});$('#settingsPanel').innerHTML=settingsPanel(sec);bindSettings(sec);}
function toggleRow(label,key,desc=''){return `<div class="switch-row"><div><strong>${label}</strong>${desc?`<div class="subtle mt-8">${desc}</div>`:''}</div><div class="switch ${state.settings[key]?'on':''}" data-toggle="${key}"></div></div>`;}
function settingsPanel(sec){
  if(sec==='appearance') return `<div class="card-title">Appearance</div><div class="color-row"><div><strong>Accent color</strong><div class="subtle">Main buttons, today marker, focus accents</div></div><input id="accentColor" type="color" value="${state.settings.accent}"></div><div class="divider"></div><div class="card-title">Status colors</div>${Object.entries(STATUS_META).map(([k,v])=>`<div class="color-row"><span>${escapeHTML(v.label)}</span><input type="color" data-status-color="${k}" value="${state.settings.statusColors[k]||v.color}"></div>`).join('')}${toggleRow('Class icons','showClassIcons','Show class icons beside assignment names.')}`;
  if(sec==='dashboard') return `<div class="card-title">Home dashboard</div>${toggleRow('Greeting card','showGreeting')}${toggleRow('Workload panel','showWorkload')}${toggleRow('Summary statistics','showStats')}${toggleRow('Next-deadline countdown','showCountdown')}${toggleRow('Class point tracking','classPointTracking','Points are separated by class.')}${toggleRow('Points section','showPoints')}${toggleRow('Mini calendar','showMiniCalendar')}${toggleRow('Custom widget board','showWidgets')}${toggleRow('Completion confetti','showConfetti','Only used occasionally for larger/high-priority assignments.')}`;
  if(sec==='calendar') return `<div class="card-title">Calendar</div>${toggleRow('Show weekends','showWeekends')}${toggleRow('Compact calendar cards','compactCalendar')}<div class="field mt-16"><label>Default view</label><select id="calendarDefault">${['month','week','agenda'].map(x=>`<option value="${x}" ${state.settings.calendarDefaultView===x?'selected':''}>${x}</option>`).join('')}</select></div>`;
  if(sec==='assignments') return `<div class="card-title">Assignments & importing</div>${toggleRow('Automatic overdue detection','autoOverdue','Can still be disabled while entering or importing data.')}${toggleRow('Automatic date-meaning detection','importDateDetection','Attempts to distinguish due, assigned, available, and event dates.')}<div class="field mt-16"><label>Recently completed period</label><input id="archiveDays" class="input" type="number" min="1" max="365" value="${state.settings.archiveDays}"></div><div class="field mt-16"><label>Date-only assignment behavior</label><select id="defaultNoTime"><option value="none" ${state.settings.defaultNoTime==='none'?'selected':''}>Keep no exact time</option><option value="23:59" ${state.settings.defaultNoTime==='23:59'?'selected':''}>Default to 11:59 PM</option></select></div>`;
  if(sec==='shortcuts') return `<div class="card-title">Keyboard shortcuts</div>${toggleRow('Enable shortcuts','enableShortcuts')}${toggleRow('Command menu','enableCommandMenu')}<div class="divider"></div>${Object.entries(state.settings.shortcuts).map(([k,v])=>`<div class="color-row"><span>${k}</span><input class="input" style="width:140px" data-shortcut="${k}" value="${escapeHTML(v)}"></div>`).join('')}`;
  return `<div class="card-title">Data & cloud sync</div><div class="switch-row"><div><strong>Cloud sync</strong><div class="subtle mt-8">${cloudConfigured()?(state.auth.user?`Signed in as ${escapeHTML(state.auth.user.email||state.auth.user.displayName||'Google user')}`:'Firebase configured — sign in to sync across devices.'):'Firebase is not configured yet. Local saving still works.'}</div></div><button id="cloudAction" class="${state.auth.user?'ghost-btn':'primary-btn'}">${state.auth.user?'Sign out':'Sign in'}</button></div><div class="flex gap-8 wrap mt-16"><button id="exportData" class="ghost-btn">Export backup</button><button id="importData" class="ghost-btn">Import backup</button><button id="resetData" class="danger-btn">Reset local data</button></div><div class="subtle mt-16">Cloud sync uses Firebase when you add your project values in <code>js/firebase-config.js</code>.</div>`;
}
function bindSettings(sec){$$('[data-toggle]').forEach(s=>s.onclick=()=>{const k=s.dataset.toggle;state.settings[k]=!state.settings[k];persist();renderSettings();});if(sec==='appearance'){const a=$('#accentColor');a.oninput=()=>{state.settings.accent=a.value;persist();};$$('[data-status-color]').forEach(i=>i.oninput=()=>{state.settings.statusColors[i.dataset.statusColor]=i.value;persist();});} if(sec==='calendar')$('#calendarDefault').onchange=e=>{state.settings.calendarDefaultView=e.target.value;state.ui.calendarView=e.target.value;persist();};if(sec==='assignments'){$('#archiveDays').onchange=e=>{state.settings.archiveDays=Number(e.target.value)||21;persist();};$('#defaultNoTime').onchange=e=>{state.settings.defaultNoTime=e.target.value;persist();};}if(sec==='shortcuts')$$('[data-shortcut]').forEach(i=>i.onchange=()=>{state.settings.shortcuts[i.dataset.shortcut]=i.value.toLowerCase();persist();});if(sec==='data'){const c=$('#cloudAction');c.onclick=handleCloudAction;$('#exportData').onclick=()=>downloadJSON(`courseflow-backup-${localISODate()}.json`,state);$('#importData').onclick=openBackupImport;$('#resetData').onclick=()=>confirmModal('Reset local data?','This erases assignments, classes, settings, and widgets from this browser.',()=>{resetLocal();state=defaultState();persist(false);render();toast('Local data reset');});}}

function openAssignmentForm(id=null,prefill={}){const existing=id?state.assignments.find(a=>a.id===id):null,a=existing||{id:uid('asg'),name:'',classId:prefill.classId||state.classes[0].id,type:'Assignment',assignedDate:'',dueDate:prefill.dueDate||'',dueTime:'',points:'',status:'notStarted',priority:'normal',description:'',notes:'',tags:[],subtasks:[],createdAt:new Date().toISOString()};showModal(`${existing?'Edit':'Add'} assignment`,`<div class="form-grid"><div class="field span-2"><label>Assignment name</label><input id="aName" class="input" value="${escapeHTML(a.name)}" autofocus></div><div class="field"><label>Class</label><select id="aClass">${state.classes.map(c=>`<option value="${c.id}" ${a.classId===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></div><div class="field"><label>Type</label><select id="aType">${TYPE_OPTIONS.map(t=>`<option ${a.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Assigned date</label><input id="aAssigned" class="input" type="date" value="${a.assignedDate||''}"></div><div class="field"><label>Due date</label><input id="aDue" class="input" type="date" value="${a.dueDate||''}"></div><div class="field"><label>Due time</label><input id="aTime" class="input" type="time" value="${a.dueTime||''}"></div><div class="field"><label>Points (optional)</label><input id="aPoints" class="input" type="number" step="0.1" min="0" value="${a.points??''}"></div><div class="field"><label>Status</label><select id="aStatus">${Object.entries(STATUS_META).filter(([k])=>k!=='overdue').map(([k,v])=>`<option value="${k}" ${a.status===k?'selected':''}>${v.label}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select id="aPriority">${PRIORITIES.map(p=>`<option value="${p}" ${a.priority===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="field span-2"><label>Tags</label><input id="aTags" class="input" placeholder="essay, chapter-3, study" value="${escapeHTML((a.tags||[]).join(', '))}"></div><div class="field span-2"><label>Description</label><textarea id="aDescription">${escapeHTML(a.description||'')}</textarea></div><div class="field span-2"><label>Notes</label><textarea id="aNotes">${escapeHTML(a.notes||'')}</textarea></div><div class="field span-2"><label>Subtasks — one per line</label><textarea id="aSubtasks">${escapeHTML((a.subtasks||[]).map(s=>`${s.done?'[x]':'[ ]'} ${s.text}`).join('\n'))}</textarea></div></div>`,()=>{const name=$('#aName').value.trim();if(!name)return toast('Give the assignment a name');const oldStatus=existing?.status;const item={...a,name,classId:$('#aClass').value,type:$('#aType').value,assignedDate:$('#aAssigned').value,dueDate:$('#aDue').value,dueTime:$('#aTime').value||'',points:$('#aPoints').value===''?null:Number($('#aPoints').value),status:$('#aStatus').value,priority:$('#aPriority').value,tags:$('#aTags').value.split(',').map(x=>x.trim()).filter(Boolean),description:$('#aDescription').value,notes:$('#aNotes').value,subtasks:$('#aSubtasks').value.split('\n').map(x=>x.trim()).filter(Boolean).map((line,i)=>({id:a.subtasks?.[i]?.id||uid('sub'),done:/^\[x\]/i.test(line),text:line.replace(/^\[(?:x| )\]\s*/i,'')})),updatedAt:new Date().toISOString()}; if(item.status==='completed'&&oldStatus!=='completed')item.completedAt=new Date().toISOString(); if(item.status!=='completed')item.completedAt=null;if(existing)state.assignments=state.assignments.map(x=>x.id===id?item:x);else state.assignments.push(item);persist();closeModal();if(item.status==='completed'&&oldStatus!=='completed')completionEffect(item);toast(existing?'Assignment updated':'Assignment added');render();},existing?'<button id="modalDelete" class="danger-btn" style="margin-right:auto">Delete</button>':''); if(existing)$('#modalDelete').onclick=()=>deleteAssignment(existing); }

function openAssignmentDetail(id){const a=state.assignments.find(x=>x.id===id);if(!a)return;const c=getClass(a.classId),s=c.scheduleOnly?{label:'Scheduled',color:c.color}:statusMeta(actualStatus(a)),done=(a.subtasks||[]).filter(x=>x.done).length,total=(a.subtasks||[]).length;showDrawer(`<div class="flex between center"><span class="pill" style="border-color:${c.color}">${escapeHTML(c.icon||'')} ${escapeHTML(c.name)}</span><button id="drawerClose" class="icon-btn">×</button></div><h2>${escapeHTML(a.name)}</h2><div class="flex wrap gap-8"><span class="pill"><span class="status-dot" style="--status-color:${s.color}"></span>${escapeHTML(s.label)}</span><span class="pill">${escapeHTML(a.priority)} priority</span><span class="pill">${escapeHTML(a.type||'Assignment')}</span></div><div class="divider"></div>${a.dueDate?`<div><strong>${c.scheduleOnly?'Scheduled':'Due'}</strong><div class="muted mt-8">${escapeHTML(formatLongDate(a.dueDate))}${a.dueTime?' • '+escapeHTML(formatTime(a.dueTime)):''}</div>${c.scheduleOnly?'<div class="subtle mt-8">Schedule-only item — not counted as a deadline and hides after this date.</div>':''}</div>`:''}${a.assignedDate?`<div class="mt-16"><strong>Assigned</strong><div class="muted mt-8">${escapeHTML(formatLongDate(a.assignedDate))}</div></div>`:''}${a.points!=null?`<div class="mt-16"><strong>Points</strong><div class="muted mt-8">${a.points}</div></div>`:''}${a.description?`<div class="mt-16"><strong>Description</strong><div class="muted mt-8">${escapeHTML(a.description).replace(/\n/g,'<br>')}</div></div>`:''}${a.notes?`<div class="mt-16"><strong>Notes</strong><div class="muted mt-8">${escapeHTML(a.notes).replace(/\n/g,'<br>')}</div></div>`:''}${total?`<div class="mt-16"><strong>Subtasks</strong><div class="subtle mt-8">${done}/${total} complete</div><div class="progress-track"><div class="progress-bar" style="width:${Math.round(done/total*100)}%"></div></div><div class="mt-12">${a.subtasks.map(st=>`<div class="checkbox-row"><span>${st.done?'✓':'○'} ${escapeHTML(st.text)}</span></div>`).join('')}</div></div>`:''}<div class="divider"></div><div class="flex gap-8 wrap"><button id="detailEdit" class="primary-btn">Edit</button>${a.status!=='completed'?`<button id="detailComplete" class="ghost-btn">Mark completed</button>`:`<button id="detailRestore" class="ghost-btn">Restore</button>`}</div>`);$('#drawerClose').onclick=closeDrawer;$('#detailEdit').onclick=()=>{closeDrawer();openAssignmentForm(id)};const comp=$('#detailComplete');if(comp)comp.onclick=()=>completeAssignment(id);const res=$('#detailRestore');if(res)res.onclick=()=>{a.status='notStarted';a.completedAt=null;a.updatedAt=new Date().toISOString();persist();closeDrawer();render();toast('Assignment restored');};}
function deleteAssignment(a){const snapshot=structuredClone(a);state.assignments=state.assignments.filter(x=>x.id!==a.id);persist();closeModal();closeDrawer();render();toast('Assignment deleted','UNDO',()=>{state.assignments.push(snapshot);persist();render();});}
function completeAssignment(id){const a=state.assignments.find(x=>x.id===id);if(!a)return;const prev={status:a.status,completedAt:a.completedAt,updatedAt:a.updatedAt};const now=new Date().toISOString();a.status='completed';a.completedAt=now;a.updatedAt=now;persist();closeDrawer();render();completionEffect(a);toast('Assignment completed','UNDO',()=>{a.status=prev.status;a.completedAt=prev.completedAt;a.updatedAt=new Date().toISOString();persist();render();});}
function completionEffect(a){if(!state.settings.showConfetti)return;if((a.points||0)<50&&!['high','urgent'].includes(a.priority))return;for(let i=0;i<26;i++){const p=document.createElement('div');p.className='confetti-piece';p.style.left=Math.random()*100+'vw';p.style.background=[state.settings.accent,'#43d69c','#ffca62','#ff5f6d'][i%4];p.style.setProperty('--drift',`${(Math.random()-.5)*220}px`);p.style.animationDelay=(Math.random()*.35)+'s';document.body.append(p);setTimeout(()=>p.remove(),2200);}}

function openDay(iso){const items=sortAssignments(activeAssignments().filter(a=>a.dueDate===iso));showDrawer(`<div class="flex between center"><div><div class="eyebrow">DAY VIEW</div><h2>${escapeHTML(formatLongDate(iso))}</h2></div><button id="drawerClose" class="icon-btn">×</button></div><div class="subtle">${items.length} item${items.length===1?'':'s'} scheduled for this day</div><div class="assignment-list mt-16">${assignmentCards(items)||empty('Nothing due')}</div><button id="dayAdd" class="primary-btn full mt-16">+ Add assignment</button>`);$('#drawerClose').onclick=closeDrawer;$('#dayAdd').onclick=()=>{closeDrawer();openAssignmentForm(null,{dueDate:iso});};bindCommon();}

function openBulkImporter(){showModal('Bulk import',`<div class="switch-row"><div><strong>Automatic date interpretation</strong><div class="subtle mt-8">Detect due vs assigned vs event vs available dates.</div></div><div id="bulkDetect" class="switch ${state.settings.importDateDetection?'on':''}"></div></div><div class="field mt-16"><label>Paste assignments</label><textarea id="bulkText" style="min-height:260px" placeholder="@class Precalculus\nHomework 3.2 due August 28 20 pts\nQuiz 3 September 2 30 pts"></textarea></div><div id="bulkPreview"></div>`,()=>importBulkConfirmed(),'');let detect=state.settings.importDateDetection;$('#bulkDetect').onclick=()=>{detect=!detect;$('#bulkDetect').classList.toggle('on',detect);preview();};$('#bulkText').oninput=preview;function preview(){const rows=parseBulk($('#bulkText').value,state.classes,{detect,defaultMeaning:'due'});$('#bulkPreview').dataset.rows=JSON.stringify(rows);$('#bulkPreview').innerHTML=rows.length?`<div class="card-title mt-16">Preview</div><div class="import-preview">${rows.map(r=>r.kind==='class-missing'?`<div class="import-row"><strong>Unknown class: ${escapeHTML(r.className)}</strong><div class="import-warning">Create this class first or use an existing @class name.</div></div>`:`<div class="import-row"><strong>${escapeHTML(r.item.name)}</strong><div class="subtle">${escapeHTML(getClass(r.item.classId).name)} • ${r.item.dueDate?`Due ${formatDate(r.item.dueDate)}`:r.item.assignedDate?`Assigned ${formatDate(r.item.assignedDate)}`:r.item.eventDate?`Event ${formatDate(r.item.eventDate)}`:'No confirmed due date'}${r.item.points!=null?` • ${r.item.points} pts`:''}</div>${r.warning?`<div class="import-warning">⚠ ${escapeHTML(r.warning)}</div>`:''}</div>`).join('')}</div>`:'';}function importBulkConfirmed(){const rows=JSON.parse($('#bulkPreview').dataset.rows||'[]'),valid=rows.filter(r=>r.kind==='assignment').map(r=>r.item);if(!valid.length)return toast('No assignments to import');state.assignments.push(...valid);persist();closeModal();render();toast(`${valid.length} assignment${valid.length===1?'':'s'} imported`);} }

function openClassForm(id=null){const c=id?getClass(id):{id:uid('class'),name:'',color:'#5d8cff',icon:'📚',teacher:'',room:'',period:'',semester:'Full Year',notes:'',link:'',scheduleOnly:false};showModal(id?'Edit class':'Add class',`<div class="form-grid"><div class="field span-2"><label>Class name</label><input id="cName" class="input" value="${escapeHTML(c.name)}"></div><div class="field"><label>Icon</label><input id="cIcon" class="input" value="${escapeHTML(c.icon||'')}"></div><div class="field"><label>Color</label><input id="cColor" type="color" class="input" value="${c.color}"></div><div class="field"><label>Teacher</label><input id="cTeacher" class="input" value="${escapeHTML(c.teacher||'')}"></div><div class="field"><label>Room</label><input id="cRoom" class="input" value="${escapeHTML(c.room||'')}"></div><div class="field"><label>Period</label><input id="cPeriod" class="input" value="${escapeHTML(c.period||'')}"></div><div class="field"><label>Semester</label><select id="cSemester">${['Fall','Spring','Full Year'].map(x=>`<option ${c.semester===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span-2"><label>Class link</label><input id="cLink" class="input" value="${escapeHTML(c.link||'')}"></div><div class="field span-2"><label>Notes</label><textarea id="cNotes">${escapeHTML(c.notes||'')}</textarea></div><div class="field span-2"><div class="switch-row"><div><strong>Schedule-only class</strong><div class="subtle mt-8">Items still appear around the site, but do not count as deadlines, never become overdue, and automatically hide after their scheduled date passes.</div></div><div id="cScheduleOnly" class="switch ${c.scheduleOnly?'on':''}"></div></div></div></div>`,()=>{const name=$('#cName').value.trim();if(!name)return toast('Give the class a name');const next={...c,name,color:$('#cColor').value,icon:$('#cIcon').value||'📚',teacher:$('#cTeacher').value,room:$('#cRoom').value,period:$('#cPeriod').value,semester:$('#cSemester').value,link:$('#cLink').value,notes:$('#cNotes').value,scheduleOnly:$('#cScheduleOnly')?.classList.contains('on')||false};if(id)state.classes=state.classes.map(x=>x.id===id?next:x);else state.classes.push(next);persist();closeModal();render();toast(id?'Class updated':'Class added');},id&&id!=='general'?'<button id="deleteClass" class="danger-btn" style="margin-right:auto">Delete class</button>':'');$('#cScheduleOnly')?.addEventListener('click',e=>e.currentTarget.classList.toggle('on'));if(id&&id!=='general')$('#deleteClass').onclick=()=>confirmModal('Delete class?','Assignments in this class will move to General.',()=>{state.assignments.forEach(a=>{if(a.classId===id)a.classId='general'});state.classes=state.classes.filter(x=>x.id!==id);persist();closeModal();render();});}
function openWidgetForm(){showModal('Add widget',`<div class="form-grid"><div class="field"><label>Type</label><select id="wType"><option value="note">Note</option><option value="text">Text</option><option value="image">Image URL</option><option value="link">Link</option></select></div><div class="field"><label>Size</label><select id="wSize"><option value="">Normal</option><option value="wide">Wide</option><option value="full">Full width</option></select></div><div class="field span-2"><label>Title</label><input id="wTitle" class="input"></div><div class="field span-2"><label>Content / URL</label><textarea id="wContent"></textarea></div></div>`,()=>{const title=$('#wTitle').value.trim()||'Untitled widget';state.widgets.push({id:uid('widget'),type:$('#wType').value,size:$('#wSize').value,title,content:$('#wContent').value});persist();closeModal();render();});}

function openCommandMenu(){if(!state.settings.enableCommandMenu)return;showModal('Command menu',`<input id="commandSearch" class="input" placeholder="Search assignments, classes, actions..." autofocus><div id="commandResults" class="command-list"></div>`,null,'',true);const input=$('#commandSearch'),results=$('#commandResults');const update=()=>{const q=input.value.toLowerCase(),commands=[{label:'Add assignment',run:()=>openAssignmentForm()},{label:'Go to Home',run:()=>setRoute('home')},{label:'Go to Calendar',run:()=>setRoute('calendar')},{label:'Go to Assignments',run:()=>setRoute('assignments')},{label:'Go to Study',run:()=>setRoute('study')},{label:'Open Settings',run:()=>setRoute('settings')},...state.assignments.map(a=>({label:`${getClass(a.classId).name} — ${a.name}`,run:()=>openAssignmentDetail(a.id)})),...state.classes.map(c=>({label:`Class — ${c.name}`,run:()=>{setRoute('classes');setTimeout(()=>openClassForm(c.id),0)}}))].filter(x=>x.label.toLowerCase().includes(q)).slice(0,12);results.innerHTML=commands.map((x,i)=>`<button class="command-item" data-command="${i}">${escapeHTML(x.label)}</button>`).join('');$$('[data-command]').forEach(b=>b.onclick=()=>{const cmd=commands[Number(b.dataset.command)];closeModal();cmd.run();});};input.oninput=update;update();}

function showModal(title,body,onSave=null,extraFoot='',wide=false){modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal ${wide?'wide':''}"><div class="modal-head"><strong>${escapeHTML(title)}</strong><button id="modalClose" class="icon-btn">×</button></div><div class="modal-body">${body}</div>${onSave||extraFoot?`<div class="modal-foot">${extraFoot}<button id="modalCancel" class="ghost-btn">Cancel</button>${onSave?'<button id="modalSave" class="primary-btn">Save</button>':''}</div>`:''}</div></div>`;$('#modalClose').onclick=closeModal;const cancel=$('#modalCancel');if(cancel)cancel.onclick=closeModal;const save=$('#modalSave');if(save)save.onclick=onSave;$('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();};}
function closeModal(){modalRoot.innerHTML='';}
function showDrawer(html){modalRoot.innerHTML=`<div class="drawer-backdrop"></div><aside class="drawer">${html}</aside>`;$('.drawer-backdrop').onclick=closeDrawer;}
function closeDrawer(){modalRoot.innerHTML='';}
function confirmModal(title,text,onConfirm){showModal(title,`<p class="muted">${escapeHTML(text)}</p>`,()=>{closeModal();onConfirm();});}
function toast(message,action='',fn=null){const el=document.createElement('div');el.className='toast';el.innerHTML=`<span>${escapeHTML(message)}</span>${action?`<button>${escapeHTML(action)}</button>`:''}`;if(action)el.querySelector('button').onclick=()=>{fn?.();el.remove();};toastRoot.append(el);setTimeout(()=>el.remove(),5000);}

async function handleCloudAction(){try{if(state.auth.user){if(stopCloudWatch){stopCloudWatch();stopCloudWatch=null;}cloudSyncUid=null;await signOutCloud();state.auth.user=null;state.auth.cloudEnabled=false;persist(false);renderSettings();toast('Signed out of cloud sync');return;}if(!cloudConfigured())return toast('Add Firebase config values first');await signIn();toast('Signed in — syncing your latest progress');}catch(e){console.error(e);toast('Cloud sign-in failed');}}
function openBackupImport(){showModal('Import backup',`<div class="field"><label>Choose CourseFlow JSON backup</label><input id="backupFile" class="input" type="file" accept="application/json,.json"></div><div class="subtle mt-16">This replaces the current local data after validation.</div>`,async()=>{const f=$('#backupFile').files[0];if(!f)return toast('Choose a backup file');try{const obj=JSON.parse(await f.text());if(!Array.isArray(obj.assignments)||!Array.isArray(obj.classes))throw new Error('bad');state={...defaultState(),...obj,auth:state.auth};persist();closeModal();render();toast('Backup imported');}catch{toast('That file is not a valid CourseFlow backup');}});}

function handleKeyboard(e){if(!state.settings.enableShortcuts)return;const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag))return;const key=e.key.toLowerCase();if((e.metaKey||e.ctrlKey)&&key==='k'){e.preventDefault();openCommandMenu();return;}const s=state.settings.shortcuts;if(key===s.new){e.preventDefault();openAssignmentForm();}else if(key===s.home)setRoute('home');else if(key===s.calendar)setRoute('calendar');else if(key===s.assignments)setRoute('assignments');else if(key===s.study)setRoute('study');else if(key===s.search){e.preventDefault();setRoute('assignments');setTimeout(()=>$('#fSearch')?.focus(),0);}}

$('#quickAddSide').onclick=()=>openAssignmentForm();$('#quickAddTop').onclick=()=>openAssignmentForm();$('#commandButton').onclick=openCommandMenu;$('#syncButton').onclick=()=>{state.ui.route='settings';state.ui.settingsSection='data';render();};document.addEventListener('keydown',handleKeyboard);

applyTheme();
if(state.settings.calendarDefaultView)state.ui.calendarView=state.ui.calendarView||state.settings.calendarDefaultView;
render();
observeAuth(user=>{if(!user){if(stopCloudWatch){stopCloudWatch();stopCloudWatch=null;}cloudSyncUid=null;state.auth.user=null;state.auth.cloudEnabled=false;saveState(state);return;}startCloudSync(user);});